def solve(I, bg, marker, seed_top, seed_left, h, w):
    R,C=len(I),len(I[0])
    O=[row[:] for row in I]
    for r in range(R):
        for c in range(C):
            if O[r][c]==marker: O[r][c]=bg
    for r in range(R):
        for c in range(C):
            if I[r][c]==marker:
                tr,tc=r-h//2, c-w//2
                for i in range(h):
                    for j in range(w):
                        rr,cc=tr+i,tc+j
                        if 0<=rr<R and 0<=cc<C: O[rr][cc]=I[seed_top+i][seed_left+j]
    return O
